package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;
import com.rpsbattle.tournament.scheduler.*;
import com.rpsbattle.tournament.ranking.*;
import com.rpsbattle.tournament.persistence.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class SeriesProgressionTest {
 Tournament cup(int bestOf,TournamentFormat format){var t=new Tournament(UUID.randomUUID().toString(),"Series",format,Instant.now());t.bestOf=bestOf;t.status=TournamentStatus.RUNNING;for(int i=0;i<2;i++)t.participants.add(new TournamentParticipant(UUID.randomUUID().toString(),null,"","P"+i,i));t.matches.addAll(format==TournamentFormat.SINGLE_ELIMINATION?new SingleEliminationScheduler().schedule(t):new RoundRobinScheduler().schedule(t));return t;}
 void finish(TournamentMatch m,String winner){m.status=TournamentMatch.Status.FINISHED;m.winnerParticipantId=winner;m.result=winner==null?"DRAW":"WIN";m.remainingA=5;m.remainingB=5;m.finishedAt=Instant.now();}
 @Test void bo3SweepStopsAtTwoGamesAndScoresOneSeriesWithoutAdvancingAfterGameOne(){var t=cup(3,TournamentFormat.SINGLE_ELIMINATION);var root=t.matches.getFirst();finish(root,root.participantA.participantId());t.matches.addAll(SingleEliminationScheduler.advance(t));assertThat(SingleEliminationScheduler.complete(t)).isFalse();assertThat(TournamentSeries.advance(t)).isTrue();String second=t.matches.getLast().id;assertThat(TournamentSeries.advance(t)).isFalse();assertThat(t.matches).hasSize(2);assertThat(t.matches.getLast().seriesId).isEqualTo(root.id);finish(t.matches.getLast(),root.participantA.participantId());assertThat(TournamentSeries.advance(t)).isFalse();t.matches.addAll(SingleEliminationScheduler.advance(t));assertThat(SingleEliminationScheduler.complete(t)).isTrue();assertThat(t.bracket.getLast().winnerParticipantId()).isEqualTo(root.participantA.participantId());var rank=new RankingService(new ClassicScoringRule()).rank(t).getFirst();assertThat(rank.played()).isEqualTo(1);assertThat(rank.wins()).isEqualTo(1);assertThat(rank.points()).isEqualTo(3);assertThat(t.matches.getLast().id).isEqualTo(second);}
 @Test void bo5ComebackCreatesFiveUniqueGamesAndAveragesTheWholeSeries(){var t=cup(5,TournamentFormat.ROUND_ROBIN);var root=t.matches.getFirst();for(int i=0;i<5;i++){finish(t.matches.getLast(),i<2?root.participantB.participantId():root.participantA.participantId());t.matches.getLast().moveCountA=2;t.matches.getLast().moveNanosA=4_000_000;if(i<4)assertThat(TournamentSeries.advance(t)).isTrue();}assertThat(TournamentSeries.advance(t)).isFalse();var result=TournamentSeries.decision(t,root).orElseThrow();assertThat(result.winnerParticipantId).isEqualTo(root.participantA.participantId());assertThat(result.moveCountA).isEqualTo(10);assertThat(t.matches.stream().map(m->m.id).distinct()).hasSize(5);assertThat(TournamentSeries.view(t,root)).containsEntry("winsA",3L).containsEntry("winsB",2L);assertThat(new RankingService(new ClassicScoringRule()).rank(t).getFirst().points()).isEqualTo(3);}
 @Test void drawCapPreservesEveryDrawAndUsesExistingKnockoutSeedPolicy(){var t=cup(3,TournamentFormat.SINGLE_ELIMINATION);var root=t.matches.getFirst();for(int i=0;i<3;i++){finish(t.matches.getLast(),null);if(i<2)TournamentSeries.advance(t);}assertThat(TournamentSeries.decision(t,root).orElseThrow().result).isEqualTo("DRAW");t.matches.addAll(SingleEliminationScheduler.advance(t));assertThat(t.bracket.getLast().resolution()).isEqualTo("DRAW_SEED");assertThat(t.matches).allMatch(m->m.winnerParticipantId==null);assertThat(TournamentSeries.advance(t)).isFalse();}
 @Test void reviewPauseAndFailureBlockNextGameAndJsonRecoveryKeepsIdentity(){var t=cup(3,TournamentFormat.ROUND_ROBIN);var root=t.matches.getFirst();finish(root,root.participantA.participantId());t.operations=t.operations.review(root.id,"check facts");assertThat(TournamentSeries.advance(t)).isFalse();t.operations=t.operations.review(root.id,null);t.status=TournamentStatus.PAUSED;assertThat(TournamentSeries.advance(t)).isFalse();t.status=TournamentStatus.RUNNING;assertThat(TournamentSeries.advance(t)).isTrue();var second=t.matches.getLast();second.status=TournamentMatch.Status.FAILED;assertThat(TournamentSeries.advance(t)).isFalse();var converter=new TournamentDetailsConverter();var saved=converter.convertToEntityAttribute(converter.convertToDatabaseColumn(TournamentDetails.snapshot(t)));var restored=new Tournament(t.id,t.name,t.format,t.createdAt);for(var m:t.matches)restored.matches.add(m.copy());saved.restore(restored);assertThat(restored.bestOf).isEqualTo(3);assertThat(restored.matches.getLast().seriesId).isEqualTo(root.id);assertThat(restored.matches.getLast().gameNumber).isEqualTo(2);assertThat(TournamentSeries.games(restored,root.id)).hasSize(2);}
 @Test void noShowForfeitsWholeSeriesAndDoubleForfeitNeverAdvances(){var t=cup(5,TournamentFormat.SINGLE_ELIMINATION);var root=t.matches.getFirst();finish(root,null);root.decisionReason="DOUBLE_FORFEIT";root.failure="NO_SHOW";assertThat(TournamentSeries.advance(t)).isFalse();t.matches.addAll(SingleEliminationScheduler.advance(t));assertThat(t.bracket.getLast().resolution()).isEqualTo("DOUBLE_FORFEIT");assertThat(t.bracket.getLast().winnerParticipantId()).isNull();assertThat(new RankingService(new ClassicScoringRule()).rank(t)).allMatch(r->r.points()==0&&r.losses()==1);}
}
